 }finally{DungeonSaveStore.editorTestPath=previous;Done=true;Summary=results.Count(r=>r.StartsWith("PASS"))+" passed / "+results.Count(r=>r.StartsWith("FAIL"))+" failed";File.WriteAllLines("Tests/KingdomTitleResults.txt",new[]{Summary}.Concat(results));Debug.Log("Kingdom title: "+Summary);}}
